function Check($label,$path){
  Write-Output "=== $label : $path ==="
  if(-not (Test-Path $path)){ Write-Output "  路径不存在"; return }
  Push-Location $path
  $top = git rev-parse --show-toplevel 2>&1
  if($LASTEXITCODE -ne 0){ Write-Output "  ❌ 不在任何 git 仓库内"; Pop-Location; return }
  Write-Output "  git 顶层: $top"
  $tracked = git ls-files . 2>&1
  if([string]::IsNullOrWhiteSpace($tracked)){ Write-Output "  ⚠️ 目录内无被跟踪文件" } else { Write-Output "  已跟踪文件数: $(($tracked | Measure-Object).Count)" }
  $st = git status --short . 2>&1
  if([string]::IsNullOrWhiteSpace($st)){ Write-Output "  工作区干净(相对顶层)" } else { Write-Output "  未提交/未跟踪:"; $st | ForEach-Object { "    $_" } }
  Pop-Location
}
